TLM.f("Commune/C2",{"officium":"Commune Unius Martyris: In virtute","rule":[],"sections":{"Introitus":[{"k":"ref","la":"Ps 20:2-3"},{"k":"text","la":"In virtúte tua, Dómine, lætábitur justus: et super salutáre tuum exsultábit veheménter: desidérium ánimæ ejus tribuísti ei."},{"k":"ref","la":"Ps 20:4"},{"k":"text","la":"Quóniam prævenísti eum in benedictiónibus dulcédinis: posuísti in cápite ejus corónam de lápide pretióso."},{"k":"macro","name":"Gloria"},{"k":"text","la":"In virtúte tua, Dómine, lætábitur justus: et super salutáre tuum exsultábit veheménter: desidérium ánimæ ejus tribuísti ei."}],"Oratio":[{"k":"text","la":"Præsta, quǽsumus, omnípotens Deus: ut, qui beáti N. Mártyris tui natalícia cólimus, intercessióne ejus, in tui nóminis amóre roborémur."},{"k":"macro","name":"Per Dominum"}],"Lectio":[{"k":"text","la":"Léctio libri Sapiéntiæ"},{"k":"ref","la":"Sap 10:10-14"},{"k":"text","la":"Justum dedúxit Dóminus per vias rectas, et ostendit illi regnum Dei, et dedit illi sciéntiam sanctórum: honestávit illum in labóribus, et complévit labores illíus. In fraude circumveniéntium illum áffuit illi, et honéstum fecit illum. Custodívit illum ab inimícis, et a seductóribus tutávit illum, et certámen forte dedit illi, ut vínceret et sciret, quóniam ómnium poténtior est sapiéntia. Hæc vénditum justum non derelíquit, sed a peccatóribus liberávit eum: descendítque cum illo in fóveam, et in vínculis non derelíquit illum, donec afférret illi sceptrum regni, et poténtiam advérsus eos, qui eum deprimébant: et mendáces osténdit, qui maculavérunt illum, et dedit illi claritátem ætérnam, Dóminus, Deus noster."}],"Graduale":[{"k":"ref","la":"Ps 111:1-2"},{"k":"text","la":"Beátus vir, qui timet Dóminum: in mandátis ejus cupit nimis."},{"k":"text","la":"Potens in terra erit semen ejus: generátio rectórum benedicétur.","mark":"V"},{"k":"text","la":"Allelúja, allelúja."},{"k":"ref","la":"Ps 20:4"},{"k":"text","la":"Posuísti, Dómine, super caput ejus corónam de lápide pretióso. Allelúja."}],"GradualeP":[{"k":"text","la":"Allelúja, allelúja."},{"k":"ref","la":"Ps 88:6"},{"k":"text","la":"Confitebúntur cœli mirabília tua, Dómine: étenim veritátem tuam in ecclésia sanctórum. Allelúja."},{"k":"ref","la":"Ps 20:4"},{"k":"text","la":"Posuísti, Dómine, super caput ejus corónam de lápide pretióso. Allelúja."}],"Tractus":[{"k":"ref","la":"Ps 111:1-2"},{"k":"text","la":"Beátus vir, qui timet Dóminum: in mandátis ejus cupit nimis."},{"k":"text","la":"Potens in terra erit semen ejus: generátio rectórum benedicétur.","mark":"V"},{"k":"sep"},{"k":"rubric","la":"Tractus"},{"k":"ref","la":"Ps 20:3-4"},{"k":"text","la":"Desidérium ánimæ ejus tribuísti ei: et voluntáte labiórum ejus non fraudásti eum."},{"k":"text","la":"Quóniam prævenísti eum in benedictiónibus dulcédinis.","mark":"V"},{"k":"text","la":"Posuísti in cápite ejus corónam de lápide pretióso.","mark":"V"}],"Evangelium":[{"k":"text","la":"Sequéntia ✠ sancti Evangélii secúndum Matthǽum"},{"k":"ref","la":"Matt 10:34-42"},{"k":"text","la":"In illo témpore: Dixit Jesus discípulis suis: Nolíte arbitrári, quia pacem vénerim míttere in terram: non veni pacem míttere, sed gládium. Veni enim separáre hóminem advérsus patrem suum, et fíliam advérsus matrem suam, et nurum advérsus socrum suam: et inimíci hóminis doméstici ejus. Qui amat patrem aut matrem plus quam me, non est me dignus: et qui amat fílium aut fíliam super me, non est me dignus. Et qui non áccipit crucem suam, et séquitur me, non est me dignus. Qui invénit ánimam suam, perdet illam: et qui perdíderit ánimam suam propter me, invéniet eam. Qui récipit vos, me récipit: et qui me récipit, récipit eum, qui me misit. Qui récipit prophétam in nómine prophétæ, mercédem prophétæ accípiet: et qui récipit justum in nómine justi, mercédem justi accípiet. Et quicúmque potum déderit uni ex mínimis istis cálicem aquæ frígidæ tantum in nómine discípuli: amen, dico vobis, non perdet mercédem suam."}],"Offertorium":[{"k":"ref","la":"Ps 8:6-7"},{"k":"text","la":"Glória et honóre coronásti eum: et constituísti eum super ópera mánuum tuárum, Dómine."}],"Secreta":[{"k":"text","la":"Munéribus nostris, quǽsumus, Dómine, precibúsque suscéptis: et cœléstibus nos munda mystériis, et cleménter exáudi."},{"k":"macro","name":"Per Dominum"}],"Communio":[{"k":"ref","la":"Matt 16:24"},{"k":"text","la":"Qui vult veníre post me, ábneget semetípsum, et tollat crucem suam, et sequátur me."}],"Postcommunio":[{"k":"text","la":"Da, quǽsumus, Dómine, Deus noster: ut, sicut tuórum commemoratióne Sanctórum temporáli gratulámur offício; ita perpétuo lætémur aspéctu."},{"k":"macro","name":"Per Dominum"}]},"hr":{"dc233e4211c917a5":{"t":"Ps 20, 2-3, Ps 20, 4\n(Ps 20, 2-3) Radi jakosti tvoje, Gospodine, veseli se pravednik i radosno kliče radi pomoći tvoje, ispunio si mu želju srca njegova. (Ps 20, 4) Pretekao si ga slatkim blagoslovom, okrunio si ga krunom od dragoga kamenja.\n<i>Slava Ocu, i Sinu, i Duhu Svetomu. Kako bijaše na početku, tako i sada i vazda i u vijeke vjekova. Amen</i>.\n(Ps 20, 2-3) Radi jakosti tvoje, Gospodine, veseli se pravednik i radosno kliče radi pomoći tvoje, ispunio si mu želju srca njegova.","kn":"(Ps. 20, 2-3). U Tvojoj se moći, Gospodine, raduje pravednik i veselo kliče u tvome spasenju, jer si mu ispunio želju njegova srca. (Ps. 20, 4) PredU'Sreo si ga slatkim blagoslovom i njegovu si glavu okrunio krunom dragoga kamenja. Slava Ocu. U Tvojoj se moći.","knRef":"Kniewald 1942, str. 792–793 (snimka 397) (OCR)"},"36bf5d79c79160f1":null,"e83d5e42a8b3608d":{"t":"Mudr 10, 10-14\nČitanje knjige Mudrosti. Gospodin je pravim putem vodio pravednika, pokazao mu Božje kraljevstvo, udijelio mu znanje svetih, obogatio ga u naporima i oplodio mu rad. Očuvao ga od varalica i obogatio ga. Zaštitio ga od neprijatelja, čuvao od zasjeda, dao mu da pobjedi u teškoj borbi i spoznao je da je mudrost jača od svega. Ona nije napustila pravednika, kada je bio prodan, nego ga je oslobodila iz ruku grješnika. I sašla je s njim u jamu i nije ga ostavila u lancima, dok mu nije pribavila vladarsko žezlo i vlast nad tlačiteljima. One koji su ga crnili otkrila je kao lašce, a njemu je Bog naš Gospodin udijelio vječnu slavu.","kn":"Čitanje Knjige mudrosti (10, 10-14). Goispodin je pravednika vodio pravim putem i pokazao mu kraljevstvo Božje i udijelio mu znanje svetih i obogatio ga u naporima i oplodio -mu rad. I pomogao mu je protiv onih, koji su ga htjeli prevariti i obogatio ga je. Štitio ga je od neprijatelja i očuvao dd 1 zasjeda i dao mu da pobijedi u teškoj borbi i da i upozna, kako je mudrost jača od svega. Ova nije [ zapustila pravednika, kad je bio prodan, nego ga I je oslobodila iz ruku grješndka. I sašla je s njim u I jamu i nije ga zapustila u lancima, sve dok mu nije pribavila kraljevskoga žezla i vlasti nad tlačiteljima. One, koji su ga ocrnili, pokaza,la je lašctma, a njemu je udijelio vječnu slavu Gospodin Bog naš.","knRef":"Kniewald 1942, str. 792–793 (snimka 397) (OCR)"},"2095fd7c6de050b3":{"t":"Ps 111, 1-2\nBlago čovjeku koji se boji Gospodina i koji uživa u njegovim zapovijedima. Silno će biti na zemlji njegovo potomstvo, rod će pravednika biti blagoslovljen.\n\nPs 20, 4\n<i>Aleluja</i>, <i>aleluja</i>.\nOkrunio si ga, Gospodine, krunom od dragoga kamenja. <i>Aleluja</i>.","kn":"(Ps. 111, 1). Blago čovjeku, koji se boji .Boga, zapovijedi njegove žudi veoma. Silno će biti na zemlji potomstvo njegovo, blagoslovit ce se rod pravih.\n\n(Ps. 20, 4). Okrunio si ga, Gospodine, krunom dragoga kamenja, aleluja.","knRef":"Kniewald 1942, str. 714–715 (snimka 358) (OCR)"},"a0641de43079cacf":{"t":"Mt 10, 34-42\nSlijedi sveto Evanđelje po Mateju. U ono vrijeme reče Isus svojim učenicima: Nemojte misliti da sam došao da svijetu donesem mir. Nisam došao donijeti mir, nego mač. Došao sam, da rastavim sina od njegova oca, kćer od njezine majke i snahu od njezine svekrve, jer su svakome čovjeku neprijatelji njegovi domaći: Tko oca ili majku ljubi više nego mene, nije mene dostojan, kao i tko ljubi sina ili kćer više nego mene nije mene dostojan. Tko ne uzme svoj križ i ne pođe za mnom, nije mene dostojan. I tko čuva svoj život izgubit će ga, a tko izgubi svoj život radi mene naći će ga. Tko prima vas, prima mene, a tko prima mene, prima onoga koji je mene poslao. Tko prima proroka zato što je prorok, primit će plaću proroka, a tko primi pravednika jer je pravednik, primit će plaću pravednika. Tko napoji čašom hladne vode jednoga od ovih malenih samo stoga što je moj učenik, zaista vam kažem, da neće izgubiti svoje plaće.","kn":"t Slijedi sveto evanđelje po Mateju (10, 34-42). U ono vrijeme reče Isus svojim učenicima: Ne mislite, da sam ja došao da zemlji donesem mir: nijesam došao da donesem mir, nego mač. A došao sam da. rastavim čovjeka od njegova oca i kćer od njezine majke i snahu od nj^lne svekrve, jer su svakomu neprijatelju njegovi domaći. Tko ljubi oca ili majku više nego mene, nije mene dostojan, i tko ljubi sina ili kćer više nego mene, nije mene dostojan. I tko ne uzme svoga križa i ne ide za mnom, nije mene dostojan. Tko nađe svoj život, izgubit će ga, a tko radi. mene izgubi svoj život, naći će ga. Tko vas prima, mene prima, a tko prima mene, prima onoga, koji je mene poslao. Tko prima proroka zato, što je prorok, primit će proročku plaću, a tko prima pravednika, jer je pravednik, primit će pravedničku plaću. I tko napoji samo čašom vode jednoga od ovih malenih, jer je Sv, Hedviga 16. X. moj učenik, zaista vam kažem, da ne će izgubiti svoje plaće.","knRef":"Kniewald 1942, str. 738–739 (snimka 370) (OCR)"},"b389ff84b79a6464":{"t":"Ps 8, 6-7\nOkrunio si ga slavom i čašću i postavio si ga nad djela svojih ruku, Gospodine.","kn":"(Ps. 8, 6-7). Okrunio si ga slavom i čašću i postavio si ga nad sva djela tvoja. Gospodine!","knRef":"Kniewald 1942, str. 790–791 (snimka 396) (OCR)"},"0741f87b36183013":{"t":"Primi, molimo, Gospodine, naše darove i molitve te nas nebeskim otajstvima očisti i milostivo usliši.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Primi, Gospodine, naše darove i molitve, te nas blago usliši i očisti nebeskim otajstvima, Po . G. n.","knRef":"Kniewald 1942, str. 572–573 (snimka 287) (OCR)"},"404159d2e4df1ef4":{"t":"Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda i svagdje zahvaljujemo tebi, Gospodine, sveti Oče, svemogući vječni Bože, po Kristu Gospodinu našemu. – Po njemu tvoje veličanstvo hvale anđeli, klanjaju se gospodstva i dršću vlasti. Nebesa i nebeske sile i blaženi serafini zajedničkim klicanjem slave. Daj, molimo, s njima i naše glase primi dok govorimo poniznim hvalospjevom:","kn":"Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda i svagdje zahvaljujemo Tebi, Gospodine sveti. Oče svemogući, vječni Bože, po Kristu, Gospotdiniu našemu, po kome veličanstvo Tvoje hvale anđeli, klanjaju Ti se gospodstva, tresu se vlasti. Nebesa Te i nebeske moći i blaženi serafini, zadružnim klicanjem zajedno slave. Zapovijedi, molimo, da se i naši glasovi združe s njihovima, smjernim isippvijedanjem govoreći:","knRef":"Kniewald 1942, str. 18–19 (snimka 10) (OCR)"},"86afb01737f7cc30":{"t":"Mt 16, 24\nTko hoće da ide za mnom, neka se odreče samoga sebe, neka uzme križ svoj i slijedi mene.","kn":"(Mat. 16, 34). Ako tko hoće za mnom da ide, neka se odreče samoga sebe, neka uzme križ svoj i neka ide za mnom.","knRef":"Kniewald 1942, str. 794–795 (snimka 398) (OCR)"},"3b6e3f0bab8b0afc":{"t":"<i>Pomolimo se</i>.\nDaj, molimo, Gospodine Bože naš, da se tako radujemo vječnim gledanjem tvojih svetih kao što se veselimo sjećanjem na njih po vremenitoj službi.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Podaj, molimo, Gospodine, Bože naž, kao sto se na zemlji radujemo svetkovini Tvojih svetih, tako da se i u vječnosti veselimo gledajući ih, po G. n.","knRef":"Kniewald 1942, str. 544–545 (snimka 273) (OCR)"}},"variants":{"paschal":{"Introitus":[{"k":"ref","la":"Ps 63:3"},{"k":"text","la":"Protexísti me, Deus, a convéntu malignántium, allelúja: a multitúdine operántium iniquitátem, allelúja, allelúja."},{"k":"ref","la":"Ps. 63:2"},{"k":"text","la":"Exáudi, Deus, oratiónem meam cum déprecor: a timóre inimíci éripe ánimam meam."},{"k":"macro","name":"Gloria"},{"k":"text","la":"Protexísti me, Deus, a convéntu malignántium, allelúja: a multitúdine operántium iniquitátem, allelúja, allelúja."}],"Lectio":[{"k":"text","la":"Léctio libri Sapiéntiæ"},{"k":"ref","la":"Sap 5:1-5"},{"k":"text","la":"Stabunt justi in magna constántia advérsus eos, qui se angustiavérunt et qui abstulérunt labóres eórum. Vidéntes turbabúntur timore horríbili, et mirabúntur in subitatióne insperátæ salútis, dicéntes intra se, poeniténtiam agéntes, et præ angústia spíritus geméntes: Hi sunt, quos habúimus aliquándo in derísum et in similitúdinem impropérii. Nos insensáti vitam illórum æstimabámus insániam, et finem illórum sine honóre: ecce, quómodo computáti sunt inter fílios Dei, et inter Sanctos sors illórum est."}],"Graduale":[{"k":"text","la":"Allelúja, allelúja."},{"k":"ref","la":"Ps 88:6"},{"k":"text","la":"Confitebúntur cœli mirabília tua, Dómine: étenim veritátem tuam in ecclésia sanctórum. Allelúja."},{"k":"ref","la":"Ps 20:4"},{"k":"text","la":"Posuísti, Dómine, super caput ejus corónam de lápide pretióso. Allelúja."}],"Evangelium":[{"k":"text","la":"Sequéntia ✠ sancti Evangélii secúndum Joánnem"},{"k":"ref","la":"Joannes 15:1-7"},{"k":"text","la":"In illo témpore: Dixit Jesus discípulis suis: Ego sum vitis vera: et Pater meus agrícola est. Omnem pálmitem in me non feréntem fructum, tollet eum: et omnem, qui fert fructum, purgábit eum, ut fructum plus áfferat. Jam vos mundi estis propter sermónem, quem locútus sum vobis. Manéte in me: et ego in vobis. Sicut palmes non potest ferre fructum a semetípso, nisi mánserit in vite: sic nec vos, nisi in me manséritis. Ego sum vitis, vos pálmites: qui manet in me, et ego in eo, hic fert fructum multum: quia sine me nihil potéstis fácere. Si quis in me non mánserit, mittétur foras sicut palmes, et aréscet, et cólligent eum, et in ignem mittent, et ardet. Si manséritis in me, et verba mea in vobis mánserint: quodcúmque voluéritis, petétis, et fiet vobis."}],"Offertorium":[{"k":"ref","la":"Ps 88:6"},{"k":"text","la":"Confitebúntur cœli mirabília tua, Dómine: et veritátem tuam in ecclésia sanctórum, allelúja, allelúja."}],"Communio":[{"k":"ref","la":"Ps 63:11"},{"k":"text","la":"Lætábitur justus in Dómino, et sperábit in eo: et laudabúntur omnes recti corde, allelúja, allelúja."}]}}});
